UPDATE p_amb_brand SET display_name='VetriPaws', intro='VetriPaws strips melt on your dog''s tongue in about 30 seconds. No pills to hide, no powder to mix. Watch a few videos below, pick one, and make your version with your own dog.', about='Vet-formulated supplement strips for dogs that dissolve on the tongue: Bone & Joint, Fresh Breath and Skin & Coat, 30 strips a tin, or all three in the Complete Bundle.', audience='Dog owners, a lot of them with an older dog, who are tired of hiding pills in cheese and want a daily routine that sticks.', accent='#005666', logo_url='https://tools.go-mobius-digital.com/angles/logos/vetripaws.png', submit_platform='TRYBE', submit_url=NULL, submit_label='Film this on TRYBE', show_inspo=1, checklist_json='{"do": [{"title": "Your dog, your home", "text": "Your own dog, your own couch, phone held close. No studio, no slideshow."}, {"title": "Show the strip go on", "text": "One unbroken shot of the strip on the tongue until it is gone."}, {"title": "Start on the moment", "text": "The pill in the cheese, the fur, the kiss. Not on hello."}], "say": ["It supports joints, breath, skin and coat. Never cures, treats or fixes.", "Vet formulated. Dissolves in about 30 seconds (that is the strip, not a result).", "30-day money-back guarantee, 30 strips a tin."], "skip": ["Vet recommended, prices or discount codes.", "Another brand''s product by name or in shot.", "Before and after health promises."]}', rules_json='["Your own dog and a real VetriPaws tin. No AI images or AI-made video.", "Say \"supports\", never \"cures\", \"treats\" or \"fixes\". No \"vet recommended\" (it is vet formulated).", "The strip dissolves in about 30 seconds. Do not promise results in seconds or days.", "No other supplement brands by name and no competitor packaging in shot.", "Prices and offers only if they are live on vetripaws.com the day you post."]', avoid_json='[{"title": "The tin held up to the camera with a list of benefits", "why": "Nobody stops for it. Show your dog taking the strip instead."}, {"title": "A dog that clearly does not want it", "why": "If your dog spits it out, film another day. Never force it."}]', pdf_json='{"line1": "VetriPaws creators,", "line2": "here''s what to film.", "intro": "Our creator hub is a board of videos that worked for other brands. Pick one, make your version with your dog and a VetriPaws strip, film it today. Read the short checklist at the bottom first.", "cta": "Your creator hub", "note": "Opens right on your phone. No login, no app.", "steps": ["Open the hub and pick a video", "Make your version with your dog", "Send it in"]}', board_mode='picked', updated_at=datetime('now') WHERE act_id='brand_vetripaws';
