INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('d9e80692b40a0f07', 'brand_vetripaws', 'b763a3101f4df13f', 1, 1, 1, 'live', 'The pill in the cheese, again', 'Every dog owner has lost the pill-in-cheese game, so the hook is instant and the strip is the obvious way out.', 'Any owner whose dog has ever found the pill', 'Any strip', 'Pill fail then the swap', '["Your dog found the pill in the cheese again, didn''t they?", "Pill pocket, peanut butter, cheese. He beat all of them.", "I found his vitamin on the kitchen floor three hours later. That''s when I quit pills."]', '[{"label": "Open · 0 to 3s", "text": "Dog spits out or sniffs around the cheese and leaves the pill. Text: your dog found the pill again, didn''t they?"}, {"label": "Middle", "text": "Open the tin, pull one strip, lay it on the dog''s tongue. Hold the shot while it melts, about 30 seconds sped up is fine."}, {"label": "Close", "text": "Dog licking lips and looking for more. Say: no hiding, no standoff, no pill on the floor."}]', 'Dog sitting in front of you with a pill hidden in cheese, text on screen: your dog found the pill again, didn''t they?', 'Close up of the strip going on the tongue and simply disappearing, no chewing, no standoff', '[{"brand": "Wuffes", "what": "Film your dog spitting the pill back out of the cheese (or show the one you found on the floor). Then lay a VetriPaws strip on their tongue and let the camera roll while it melts away.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('f12641e3fca4269b', 'brand_vetripaws', 'd9e80692b40a0f07', 'upload', 'amb/brand_vetripaws/inspo-wuf-pill-cheese.mp4', 'Wuffes (inspiration)', 'Film your dog spitting the pill back out of the cheese (or show the one you found on the floor). Then lay a VetriPaws strip on their tongue and let the camera roll while it melts away.', 'b763a3101f4df13f', 1, 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('33f89f1cb1b0ef26', 'brand_vetripaws', '6d9129279acc7d56', 1, 2, 2, 'live', 'My old dog tells the story', 'Dog-voice captions make people stop, and owners of older dogs see their own dog in every clip.', 'Owner of a senior or big-breed dog', 'Bone & Joint', 'Dog POV captions', '["Mom, I''m getting older and I need to tell you something.", "I''m 11. Getting off the couch takes me a minute now.", "Every time I pant after a walk, it''s a little signal."]', '[{"label": "Open · 0 to 3s", "text": "Tight shot of your dog''s face, caption in the dog''s voice about getting older."}, {"label": "Middle", "text": "Clips of the slow parts: getting up after a nap, stairs, sniffing slowly in the yard. Then the strip going on the tongue at breakfast."}, {"label": "Close", "text": "Dog walking on the leash in good light. Caption: thanks for giving me what my joints need. More walks together."}]', 'Close up of the old dog''s face with caption: Mom, I wish you could tell what my joints feel like', 'The strip moment told by the dog: she gives me this thing that melts on my tongue', '[{"brand": "Dog is Human", "what": "Film your older dog through a normal day (slow off the bed, the stairs, the walk) and write the captions in your dog''s voice. Show the strip as part of the morning and end on the walk.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('39165ef63012be52', 'brand_vetripaws', '33f89f1cb1b0ef26', 'upload', 'amb/brand_vetripaws/inspo-dih-senior-pov.mp4', 'Dog is Human (inspiration)', 'Film your older dog through a normal day (slow off the bed, the stairs, the walk) and write the captions in your dog''s voice. Show the strip as part of the morning and end on the walk.', '6d9129279acc7d56', 1, 1, 2);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('43d53a6cb5f89bbf', 'brand_vetripaws', '628f028815b55001', 1, 3, 3, 'live', 'It wasn''t my husband''s breath', 'A tiny skit with a twist ending gets watched to the end and shares well, and every dog owner knows morning dog breath.', 'A couple (or roommates) with a dog that sleeps in the bed', 'Fresh Breath', 'Two-person bed skit', '["For the longest time I thought my husband had terrible morning breath.", "Turns out it wasn''t him. It was the dog.", "Morning breath in our bed has a name, and it''s Biscuit."]', '[{"label": "Open · 0 to 3s", "text": "Both in bed, one turns away from the other with a face. Text: bad morning breath?"}, {"label": "Middle", "text": "Dog lifts its head from the blanket. Cut to the kitchen: strip on the tongue, melts while you make coffee."}, {"label": "Close", "text": "Back in bed, dog gives a kiss and nobody flinches. Say: one strip in the morning, that''s it."}]', 'Partner waking up and recoiling. Text: bad morning breath?', 'The reveal: the dog pops its head up between you', '[{"brand": "Zesty Paws", "what": "Two people in bed, one rolls over and makes a face at the partner. Reveal the dog between you is the real culprit, then show the strip as part of your morning.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('0ca225ea66054630', 'brand_vetripaws', '43d53a6cb5f89bbf', 'upload', 'amb/brand_vetripaws/inspo-zp-morning-breath.mp4', 'Zesty Paws (inspiration)', 'Two people in bed, one rolls over and makes a face at the partner. Reveal the dog between you is the real culprit, then show the strip as part of your morning.', '628f028815b55001', 1, 1, 3);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('46cd3398c6a11af1', 'brand_vetripaws', 'ae4bbbea42011e24', 1, 4, 4, 'live', 'A jar full of my dog''s fur', 'A jar of fur is a visual nobody scrolls past, and it says shedding without a single word.', 'Owner of a heavy shedder (lab, husky, shepherd, golden)', 'Skin & Coat', 'Talking head with a prop', '["If you vacuum dog hair every single day, watch this.", "This is one day of fur. One day.", "Yes, dogs shed. But all year long?"]', '[{"label": "Open · 0 to 3s", "text": "Jar of fur held right up to the lens."}, {"label": "Middle", "text": "Fur on the couch, on your clothes, on the bed. Back to you talking: the coat starts with the skin. Strip on the tongue, gone in about 30 seconds."}, {"label": "Close", "text": "Hand running down your dog''s coat. Say you''re giving their skin and coat some daily support, and that it comes with a 30 day money back guarantee."}]', 'A clear jar packed with dog hair held up to the camera', 'Hand swipe across the couch or black pants, covered in fur', '[{"brand": "Petsmont", "what": "Hold up a jar (or bag) of fur you collected from one day of vacuuming and talk to camera about the shedding. Show the couch, your clothes, then the strip as your daily step.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('627e1da6c9ab1642', 'brand_vetripaws', '46cd3398c6a11af1', 'upload', 'amb/brand_vetripaws/inspo-pts-fur-vacuum.mp4', 'Petsmont (inspiration)', 'Hold up a jar (or bag) of fur you collected from one day of vacuuming and talk to camera about the shedding. Show the couch, your clothes, then the strip as your daily step.', 'ae4bbbea42011e24', 1, 1, 4);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('9d04251537991e81', 'brand_vetripaws', 'b763a3101f4df13f', 0, 0, 5, 'live', 'I tried everything', 'Owners of picky dogs feel seen by the montage of failed tricks, and the strip ends the search.', 'Owner of a picky or suspicious dog', 'Any strip', 'Frustrated owner montage', '["I''ve tried everything to get my dog to take his vitamins.", "Cheese, peanut butter, pill pockets, crushing it into dinner. Nothing.", "My dog can find a pill in a meatball from across the room."]', '[{"label": "Open · 0 to 3s", "text": "Dog sniffing the bowl and walking off. You shrug at camera."}, {"label": "Middle", "text": "Quick cuts of each trick failing. Then the tin, one strip, on the tongue."}, {"label": "Close", "text": "Dog licks lips and stares at the tin. Say: finally, something he actually takes."}]', 'Dog walking away from a bowl you clearly worked hard on', 'The pile of failed tricks on the counter', '[{"brand": "Pupford", "what": "Show every trick you''ve used to get a vitamin into your dog: pill pockets, cheese, peanut butter, crushing it into food. Then the strip, which just goes on the tongue.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('ce2fa23edcd1b685', 'brand_vetripaws', '9d04251537991e81', 'upload', 'amb/brand_vetripaws/inspo-pup-tried-everything.mp4', 'Pupford (inspiration)', 'Show every trick you''ve used to get a vitamin into your dog: pill pockets, cheese, peanut butter, crushing it into food. Then the strip, which just goes on the tongue.', 'b763a3101f4df13f', 1, 1, 5);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('1de591ad45572d3f', 'brand_vetripaws', '6d9129279acc7d56', 0, 0, 6, 'live', 'Warning: don''t give this to your old dog', 'A fake warning is a pattern break, and the payoff is a happy older dog moving around.', 'Owner of an older dog who still has spark', 'Bone & Joint', 'Fake warning skit', '["Warning: your dog will start asking for this.", "Now he waits by the tin every morning, and then the leash.", "Nobody warned me about this part."]', '[{"label": "Open · 0 to 3s", "text": "Tin in hand. Text: WARNING."}, {"label": "Middle", "text": "Clips of your dog playing, running up to you, going up steps. Strip on the tongue at breakfast."}, {"label": "Close", "text": "Dog sitting proud next to the tin. Say you''re supporting their joints every day."}]', 'Text on screen: WARNING, don''t buy this', 'Dog zooming through the house', '[{"brand": "Wuffes", "what": "Joke warning up front, then clips of your older dog being bouncy: running to the door, jumping on the bed, playing in the yard. Show the strip in the morning routine.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('8104d6e30436794c', 'brand_vetripaws', '1de591ad45572d3f', 'upload', 'amb/brand_vetripaws/inspo-wuf-warning-puppy.mp4', 'Wuffes (inspiration)', 'Joke warning up front, then clips of your older dog being bouncy: running to the door, jumping on the bed, playing in the yard. Show the strip in the morning routine.', '6d9129279acc7d56', 1, 1, 6);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('d77ca0fcbaa9e848', 'brand_vetripaws', '628f028815b55001', 0, 0, 7, 'live', 'Kisses that smell like fish', 'The recoil is funny and true, and the strip is easier than brushing.', 'Owner whose dog loves face kisses', 'Fresh Breath', 'Kiss recoil, before and after', '["Tired of puppy kisses that smell like fish?", "I love him. I do not love his breath.", "Brushing his teeth every day? Be serious."]', '[{"label": "Open · 0 to 3s", "text": "Dog kiss, you recoil."}, {"label": "Middle", "text": "Toothbrush struggle on the couch. Then strip on the tongue, gone."}, {"label": "Close", "text": "Kiss again, you lean in. Say you''re supporting fresher breath with one strip a day."}]', 'Dog licking your face and you turning away', 'Wrestling a toothbrush into your dog''s mouth', '[{"brand": "PetLab Co.", "what": "Your dog goes in for a kiss and you pull back with a face. Show how you used to fight with a toothbrush, then the strip, then a kiss you don''t dodge.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('ca932961e7434557', 'brand_vetripaws', 'd77ca0fcbaa9e848', 'upload', 'amb/brand_vetripaws/inspo-plc-fish-kisses.mp4', 'PetLab Co. (inspiration)', 'Your dog goes in for a kiss and you pull back with a face. Show how you used to fight with a toothbrush, then the strip, then a kiss you don''t dodge.', '628f028815b55001', 1, 1, 7);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('3090ab367596d559', 'brand_vetripaws', 'ae4bbbea42011e24', 0, 0, 8, 'live', 'Two owners, one itchy dog', 'Two real people talking about their own dog feels honest and is easy to film at home.', 'A couple, older owners work great here', 'Skin & Coat', 'Two-person talk to camera', '["We tried everything for her itching.", "Him: shampoos. Me: creams. Her: still scratching.", "Here''s what we wish we''d known a year ago."]', '[{"label": "Open · 0 to 3s", "text": "Both of you with the dog between your legs."}, {"label": "Middle", "text": "Close ups of the scratching. The shelf of stuff you tried. Strip on the tongue."}, {"label": "Close", "text": "Unboxing the tin with the dog sniffing it. Both say why you''re sticking with it."}]', 'Couple standing side by side with the dog sitting between them', 'The pile of shampoos and creams that didn''t stop it', '[{"brand": "Dog is Human", "what": "Stand with your partner and your dog and talk about the scratching together, trading lines. Show the bottles and creams you tried, then the strip.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('d6f30b238cf516ce', 'brand_vetripaws', '3090ab367596d559', 'upload', 'amb/brand_vetripaws/inspo-dih-couple-itchy.mp4', 'Dog is Human (inspiration)', 'Stand with your partner and your dog and talk about the scratching together, trading lines. Show the bottles and creams you tried, then the strip.', 'ae4bbbea42011e24', 1, 1, 8);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('81f8b29fdcab8d5d', 'brand_vetripaws', 'b763a3101f4df13f', 0, 0, 9, 'live', 'Picky eater? Never heard of her', 'A quick meme format with one clean payoff, easy to film in one take.', 'Anyone with a dog that is fussy about pills', 'Any strip', 'Meme caption, one beat', '["Picky eater? Never heard of her.", "She refuses every pill. Watch this.", "The pickiest dog I know, versus one strip."]', '[{"label": "Open · 0 to 3s", "text": "Your dog side-eyeing a pill or a bowl. Text: picky eater?"}, {"label": "Middle", "text": "Strip out of the tin, dog takes it on the tongue. Text: never heard of her."}, {"label": "Close", "text": "Dog sitting waiting for another one."}]', 'Text on screen: picky eater?', 'The dog leaning in for the strip', '[{"brand": "Pupford", "what": "Short and funny: text says picky eater, then your dog happily takes the strip off your fingers like it''s a treat. Under 15 seconds.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('98bd15f0d6bf1b8c', 'brand_vetripaws', '81f8b29fdcab8d5d', 'upload', 'amb/brand_vetripaws/inspo-pup-never-heard.mp4', 'Pupford (inspiration)', 'Short and funny: text says picky eater, then your dog happily takes the strip off your fingers like it''s a treat. Under 15 seconds.', 'b763a3101f4df13f', 1, 1, 9);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('a2e1986bac1d11be', 'brand_vetripaws', '6d9129279acc7d56', 0, 0, 10, 'live', 'I wish I started sooner', 'Regret from a real owner is more convincing than any claim, and it pushes younger-dog owners too.', 'Owner of a very old dog, or someone with an old and a young dog', 'Bone & Joint', 'Talking head, holding the dog', '["One thing I wish I did way sooner with my old dog.", "He''s 14. Here''s my one regret.", "If your dog is 6 or older, don''t sleep on this."]', '[{"label": "Open · 0 to 3s", "text": "You with your dog in your arms, talking to camera."}, {"label": "Middle", "text": "Put the dog down, open the tin, read the label out loud (vet formulated, Bone & Joint), strip on the tongue."}, {"label": "Close", "text": "Say: don''t wait like I did."}]', 'You holding your senior dog, finger up: one thing I wish I did sooner', 'The strip melting on your old dog''s tongue', '[{"brand": "Wuffes", "what": "Hold your older dog and talk straight to camera about the one thing you wish you''d started earlier: daily joint support. Show the tin and a strip going on.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('d5c95816f97194b6', 'brand_vetripaws', 'a2e1986bac1d11be', 'upload', 'amb/brand_vetripaws/inspo-wuf-wish-sooner.mp4', 'Wuffes (inspiration)', 'Hold your older dog and talk straight to camera about the one thing you wish you''d started earlier: daily joint support. Show the tin and a strip going on.', '6d9129279acc7d56', 1, 1, 10);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('5f641816928af921', 'brand_vetripaws', '628f028815b55001', 0, 0, 11, 'live', 'I couldn''t cuddle him anymore', 'Losing the cuddles is the real pain behind bad breath, and owners feel it.', 'Owner of a small dog that loves to cuddle', 'Fresh Breath', 'Talking head with the dog in frame', '["I stopped letting my dog give me kisses, and I felt terrible about it.", "His breath could clear a room.", "You know it''s bad when your guests mention it."]', '[{"label": "Open · 0 to 3s", "text": "Lift the lip, show the teeth close up."}, {"label": "Middle", "text": "You on the couch with the dog, talking. Strip on the tongue, short close up."}, {"label": "Close", "text": "Dog in your arms, face to face, no flinching."}]', 'Lifting your dog''s lip to show the teeth', 'You admit you''ve been turning away from your own dog', '[{"brand": "Native Pet", "what": "Sit with your dog and tell it straight: the breath got so bad you stopped letting them close. Show a quick look at their teeth, the strip going on, and the cuddle at the end.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('2ca59e010a41c4e2', 'brand_vetripaws', '5f641816928af921', 'upload', 'amb/brand_vetripaws/inspo-nat-breath-talk.mp4', 'Native Pet (inspiration)', 'Sit with your dog and tell it straight: the breath got so bad you stopped letting them close. Show a quick look at their teeth, the strip going on, and the cuddle at the end.', '628f028815b55001', 1, 1, 11);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('afc1154316492884', 'brand_vetripaws', 'ae4bbbea42011e24', 0, 0, 12, 'live', 'The scratching that never stops', 'Owners recognise the constant scratching instantly, and the calm ending is what they want.', 'Owner of a small or medium itchy dog', 'Skin & Coat', 'Problem montage, then routine', '["Scratch. Scratch. Scratch. All day.", "If your dog can''t stop scratching, keep watching.", "Creams work on the outside. I wanted something for the inside."]', '[{"label": "Open · 0 to 3s", "text": "Dog scratching, fast cuts."}, {"label": "Middle", "text": "Strip on the tongue, the dog licking lips."}, {"label": "Close", "text": "Dog relaxed on your lap, you smiling at camera."}]', 'Dog mid-scratch on the rug', 'Third scratch clip in a row, you sigh', '[{"brand": "Native Pet", "what": "Quick clips of your dog scratching on the rug, on the couch, in the yard. Then the strip as your daily step and a calm dog on your lap.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('984ff36b70224cf5', 'brand_vetripaws', 'afc1154316492884', 'upload', 'amb/brand_vetripaws/inspo-nat-cavalier-itch.mp4', 'Native Pet (inspiration)', 'Quick clips of your dog scratching on the rug, on the couch, in the yard. Then the strip as your daily step and a calm dog on your lap.', 'ae4bbbea42011e24', 1, 1, 12);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('23f834f5eb736c17', 'brand_vetripaws', 'b763a3101f4df13f', 0, 0, 13, 'live', 'Her favorite part of the day', 'Seeing a dog get excited for a supplement answers the only question that matters: will mine take it?', 'Owner with a food-motivated dog, or two dogs', 'Any strip', 'Daily routine voiceover', '["This is my dog''s favorite part of the day.", "Ironically, it''s also the healthiest part of his day.", "Watch what happens when I open this tin."]', '[{"label": "Open · 0 to 3s", "text": "Tin opens, dog runs in."}, {"label": "Middle", "text": "Strip on the tongue, close up while it melts. Say how much easier this is than a pill."}, {"label": "Close", "text": "Both dogs (or one) sitting pretty for theirs."}]', 'Dog sprinting into the kitchen at the sound of the tin', 'Strip on the tongue, gone, dog asking for more', '[{"brand": "Ruff Greens", "what": "Film your dog running to you when the VetriPaws tin comes out. Talk over it: this is the healthiest part of their day and they think it''s a treat.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('a9474aacae091ccb', 'brand_vetripaws', '23f834f5eb736c17', 'upload', 'amb/brand_vetripaws/inspo-rg-favorite-part.mp4', 'Ruff Greens (inspiration)', 'Film your dog running to you when the VetriPaws tin comes out. Talk over it: this is the healthiest part of their day and they think it''s a treat.', 'b763a3101f4df13f', 1, 1, 13);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('7a3285dda3bb41d3', 'brand_vetripaws', '6d9129279acc7d56', 0, 0, 14, 'live', 'A day with my dog', 'Day-in-the-life clips feel like a friend''s post, not an ad, and the strip fits naturally into the morning.', 'Active owner who walks or runs with their dog', 'Bone & Joint', 'Day in the life vlog', '["This is Koda. He''s 9 and he still wants to run every day.", "Come with us for a day.", "Here''s how I keep my old boy moving."]', '[{"label": "Open · 0 to 3s", "text": "Dog running toward you on grass, name on screen."}, {"label": "Middle", "text": "Kitchen in the morning, strip on the tongue, food bowl, leash."}, {"label": "Close", "text": "Fetch or a walk in the park. Thumbs up to camera."}]', 'Your dog running at the camera. Text: this is Koda (your dog''s name)', 'Morning routine: strip on the tongue before the walk', '[{"brand": "Native Pet", "what": "Introduce your dog by name, then film your day together: morning strip, the walk, the park. Talk over it like a vlog.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('0e47a9f869f30a41', 'brand_vetripaws', '7a3285dda3bb41d3', 'upload', 'amb/brand_vetripaws/inspo-nat-day-with-koda.mp4', 'Native Pet (inspiration)', 'Introduce your dog by name, then film your day together: morning strip, the walk, the park. Talk over it like a vlog.', '6d9129279acc7d56', 1, 1, 14);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('c2279c969e0aa889', 'brand_vetripaws', '628f028815b55001', 0, 0, 15, 'live', '3 things that aren''t just quirks', 'A simple 3 point list teaches something in seconds and makes the viewer check their own dog.', 'Confident creator who likes talking to camera', 'Fresh Breath', '3 reasons list', '["Bad breath, yellow buildup, hating the toothbrush. Those aren''t quirks.", "3 things about your dog''s mouth you shouldn''t ignore.", "If your dog does number 3, this is for you."]', '[{"label": "Open · 0 to 3s", "text": "You in the kitchen, hold up 1 finger."}, {"label": "Middle", "text": "Each sign with a quick clip of your own dog. Then the tin and a strip on the tongue."}, {"label": "Close", "text": "Say: one strip a day supports fresher breath, no brushing battle."}]', 'You holding up a toothbrush and a dog chew. Text: these aren''t quirks', 'Number 3: the toothbrush fight', '[{"brand": "PetLab Co.", "what": "Stand in your kitchen and count off 3 signs on your fingers: bad breath, yellow buildup, hating the toothbrush. Then show the strip as your easy daily step.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('a8feb497a8652dee', 'brand_vetripaws', 'c2279c969e0aa889', 'upload', 'amb/brand_vetripaws/inspo-plc-breath-signs.mp4', 'PetLab Co. (inspiration)', 'Stand in your kitchen and count off 3 signs on your fingers: bad breath, yellow buildup, hating the toothbrush. Then show the strip as your easy daily step.', '628f028815b55001', 1, 1, 15);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('87bf3d4508da06ac', 'brand_vetripaws', 'ae4bbbea42011e24', 0, 0, 16, 'live', 'My honest review', 'A plain selfie review from a real owner is the most trusted format on the feed.', 'Any owner comfortable talking to the front camera', 'Skin & Coat', 'Selfie honest review', '["Okay, my honest review after a month.", "I was not sure about this, so here''s the truth.", "She can''t get enough of it, which never happens."]', '[{"label": "Open · 0 to 3s", "text": "Selfie shot, tin up to the lens."}, {"label": "Middle", "text": "Flip to your dog, give the strip, feel the coat on camera."}, {"label": "Close", "text": "Back to you. Say what you noticed and mention the 30 day money back guarantee."}]', 'You holding up the tin close to the lens', 'Your dog pushing into frame for the strip', '[{"brand": "A Dog Called Ducky", "what": "Talk to your front camera holding the tin, with your dog wandering into frame. Give your honest take: the itching, the coat, and whether your dog actually takes it.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('24af285df1fbf54c', 'brand_vetripaws', '87bf3d4508da06ac', 'upload', 'amb/brand_vetripaws/inspo-ducky-honest-review.mp4', 'A Dog Called Ducky (inspiration)', 'Talk to your front camera holding the tin, with your dog wandering into frame. Give your honest take: the itching, the coat, and whether your dog actually takes it.', 'ae4bbbea42011e24', 1, 1, 16);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('15f96f9aadbb66ea', 'brand_vetripaws', 'b763a3101f4df13f', 0, 0, 17, 'live', 'Replying to: does your dog actually take it?', 'A comment reply feels like an honest answer to a real question, which is exactly the doubt people have about supplements.', 'Creator with a dog that sits in their lap', 'Any strip', 'Comment reply', '["Everyone keeps asking if my dog actually takes these.", "Replying to Sarah: yes, and I''ll show you.", "You asked how I get vitamins into him. Here''s the whole thing."]', '[{"label": "Open · 0 to 3s", "text": "Comment on screen, you holding your dog."}, {"label": "Middle", "text": "Open the tin, one strip, on the tongue. Keep the camera on it till it''s gone."}, {"label": "Close", "text": "Say there''s nothing to hide in food and it comes with a 30 day money back guarantee."}]', 'Comment bubble on screen, you and your dog on the couch', 'The full melt shown in one unbroken shot', '[{"brand": "Spot & Tango", "what": "Put a real comment on screen (does your dog actually take it?) with your dog in your lap, then answer by showing it: strip on the tongue, start to finish.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('43c759a66329545a', 'brand_vetripaws', '15f96f9aadbb66ea', 'upload', 'amb/brand_vetripaws/inspo-snt-comment-reply.mp4', 'Spot & Tango (inspiration)', 'Put a real comment on screen (does your dog actually take it?) with your dog in your lap, then answer by showing it: strip on the tongue, start to finish.', 'b763a3101f4df13f', 1, 1, 17);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('32f69824903abb7a', 'brand_vetripaws', '6d9129279acc7d56', 0, 0, 18, 'live', 'The question everyone asks about my dog', 'Owners trust another owner answering a real question more than any pitch, and the walk footage makes the point without a word.', 'Owners of older or stiff dogs who get asked about their dog on walks', 'Bone & Joint', 'FAQ captions over walk footage', '["Why does my dog get a strip every morning? The question I get asked most.", "No, it''s not candy. Here''s what I give him before every walk.", "People at the park keep asking what I give her. So here it is."]', '[{"label": "Open · 0 to 3s", "text": "Walk shot from behind, phone low. Caption: why does my dog get a strip every single morning?"}, {"label": "Middle", "text": "Quick kitchen shot: tin open, strip on the tongue until it''s gone. Captions: it supports his joints, it''s vet formulated, he takes it like a snack."}, {"label": "Close", "text": "Back on the walk, dog trotting ahead. Caption: it''s just part of our morning now."}]', 'Dog walking away from camera on the trail, caption: why does my dog get a strip every single morning?', 'Cut to the kitchen: strip on the tongue, gone in about 30 seconds, then back out the door', '[{"brand": "Wagwear", "what": "Answer the one question people always ask about your older dog, in captions over your normal walk. Why does he get a strip every morning? Show it going on, then let the walk do the talking.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('adb651c591e97de8', 'brand_vetripaws', '32f69824903abb7a', 'upload', 'amb/brand_vetripaws/inspo-wag-alfie-shoes.mp4', 'Wagwear (inspiration)', 'Answer the one question people always ask about your older dog, in captions over your normal walk. Why does he get a strip every morning? Show it going on, then let the walk do the talking.', '6d9129279acc7d56', 1, 1, 18);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('07997c5f51f182f1', 'brand_vetripaws', '628f028815b55001', 0, 0, 19, 'live', 'I''d rather do his breath than ...', 'An odd claim in the first line makes people stay for the why, and the why is how easy the strip is.', 'Owners who gave up on the toothbrush', 'Fresh Breath', 'Odd claim hook, talking head outside', '["I''d rather do my dog''s breath than my husband''s. Hear me out.", "I''d rather freshen his breath than mine, and that''s saying something.", "You''re going to think this is weird, but dog breath is the easy part of my day."]', '[{"label": "Open · 0 to 3s", "text": "Talking head outside, tin in hand. Say the ''I''d rather'' line."}, {"label": "Middle", "text": "Cut to the strip on the dog''s tongue, then back to you: no brush, no fight, it''s gone in about 30 seconds and supports fresh breath."}, {"label": "Close", "text": "Pick up or hug the dog with the tin in frame. Say: and now I actually want the kisses."}]', 'You outside, straight to camera, holding the tin: I''d rather do my dog''s breath than my husband''s', 'Quick cut of the strip going on the tongue, no brush, no wrestling', '[{"brand": "Meow Mouth", "what": "Open with a funny ''I''d rather'' line straight to camera outside, then say why breath care stopped being a fight. End holding your dog with the tin.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('df342d043e98508b', 'brand_vetripaws', '07997c5f51f182f1', 'upload', 'amb/brand_vetripaws/inspo-mm-id-rather.mp4', 'Meow Mouth (inspiration)', 'Open with a funny ''I''d rather'' line straight to camera outside, then say why breath care stopped being a fight. End holding your dog with the tin.', '628f028815b55001', 1, 1, 19);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('fe0f0180a0e86016', 'brand_vetripaws', 'ae4bbbea42011e24', 0, 0, 20, 'live', 'Bath day with my most dramatic client', 'Grooming drama is fun to watch, and the brush is the natural place to talk about coat and shedding.', 'Owners who bathe and brush at home', 'Skin & Coat', 'Groom with me, funny captions', '["My worst client is back. Send help.", "Bath day. He has already filed a complaint.", "Grooming my most dramatic client, again."]', '[{"label": "Open · 0 to 3s", "text": "Dog in the tub or sink looking betrayed. Caption: my worst client is back, send help."}, {"label": "Middle", "text": "Towel off, brushing on the floor. Captions: brush day, then the strip goes on, it supports skin and coat from the inside."}, {"label": "Close", "text": "Fluffy dog lying down, done. Caption: client satisfied, tip paid in kisses."}]', 'Wet, unimpressed dog in the tub staring at the camera, caption: my worst client is back, send help', 'Close up of the brush after the session, caption: less fur in here than last month', '[{"brand": "Rhykin Pet Co", "what": "Film bath and brush day at home like your dog is your hardest customer. Funny captions about the drama, then the brush, and the strip as the reward at the end.", "url": null}]');
