INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('eb4d533b8286652b', 'brand_vetripaws', 'b763a3101f4df13f', 0, 0, 21, 'live', 'The pile versus one strip', 'The cluttered table makes the point that most of that stuff never got eaten, and one strip is simple.', 'Owner who has a cupboard full of half-used supplements', 'Complete Bundle or Any strip', 'Table demo, talking to camera', '["This is everything I''ve bought my dog that he refused to eat.", "Half of these are still full.", "A supplement only works if your dog actually takes it."]', '[{"label": "Open · 0 to 3s", "text": "Wide shot of the cluttered table, you behind it."}, {"label": "Middle", "text": "Pick up a couple and say what went wrong (spat out, wouldn''t touch the bowl). Push it all aside. One strip."}, {"label": "Close", "text": "Dog takes the strip. Say the controlling line: it only works if they take it."}]', 'A table covered in half-used tubs and pill bottles', 'Sweeping the pile aside', '[{"brand": "PetLab Co.", "what": "Line up every pill, powder and chew you''ve bought for your dog on the table. Push it all aside, hold up one VetriPaws strip, and give it to your dog.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('6ed4962de68ee7ad', 'brand_vetripaws', 'eb4d533b8286652b', 'upload', 'amb/brand_vetripaws/inspo-plc-supplement-pile.mp4', 'PetLab Co. (inspiration)', 'Line up every pill, powder and chew you''ve bought for your dog on the table. Push it all aside, hold up one VetriPaws strip, and give it to your dog.', 'b763a3101f4df13f', 1, 1, 21);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('3474b755093513d1', 'brand_vetripaws', '6d9129279acc7d56', 0, 0, 22, 'live', 'Tin in hand, then come on the walk', 'The tin and the dog share the first frame, so the viewer gets the product and the payoff in one second.', 'Senior dog owners who still walk every day', 'Bone & Joint', 'Walk with me voiceover, product up front', '["These are the strips my old girl gets every morning. Come on our walk.", "Holding the tin, but watch who''s behind it.", "She''s eleven. Come walk with us."]', '[{"label": "Open · 0 to 3s", "text": "Tin held up close, dog in the background. Say: these are the strips she gets every morning."}, {"label": "Middle", "text": "Flip to the walk, phone at dog height. Talk over it: one strip on the tongue, dissolves in about 30 seconds, supports her joints."}, {"label": "Close", "text": "Dog trotting ahead or looking back at you. Say: this is our favorite part of the day."}]', 'VetriPaws tin held close to the lens, older dog sniffing around right behind it', 'Dog trotting to catch up with you on the path, voice says: look at her go', '[{"brand": "Pawprint Lab", "what": "Start holding the tin up close with your dog behind it, then flip to the walk and talk over it like you''re telling a friend. Keep it loose and real, just you, the dog and the trail.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('8f82f3bd70844a7e', 'brand_vetripaws', '3474b755093513d1', 'upload', 'amb/brand_vetripaws/inspo-ppl-holly-walk.mp4', 'Pawprint Lab (inspiration)', 'Start holding the tin up close with your dog behind it, then flip to the walk and talk over it like you''re telling a friend. Keep it loose and real, just you, the dog and the trail.', '6d9129279acc7d56', 1, 1, 22);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('e91d1d1234e6fcf9', 'brand_vetripaws', '628f028815b55001', 0, 0, 23, 'live', 'Listen up, dog dads', 'Calling out one group (dog dads) makes them stop scrolling, and most breath ads only talk to moms.', 'Dog dads, any breed', 'Fresh Breath', 'Dog dad call-out, holding the dog', '["Listen up fellas. That breath is not normal.", "Dog dads, we need to talk about the face licks.", "Fellas, if you''re dodging your own dog''s kisses, this one''s for you."]', '[{"label": "Open · 0 to 3s", "text": "Holding the dog, straight to camera: listen up fellas."}, {"label": "Middle", "text": "Tell it plain: the breath was bad, the toothbrush was a joke, now it''s one strip a day that dissolves on the tongue and supports fresh breath. Show it go on."}, {"label": "Close", "text": "Dog licks his face, he takes it. Say: I live in my house again, not his mouth."}]', 'Guy in the kitchen holding his dog like a baby: listen up fellas', 'Strip on the tongue in close up, then the dog licks his face and he doesn''t flinch', '[{"brand": "PrettyLitter", "what": "A dog dad holds his dog and talks straight to the other dog dads about the breath they''ve been putting up with. Keep it dry and funny, then show the strip.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('7d50a131e085473f', 'brand_vetripaws', 'e91d1d1234e6fcf9', 'upload', 'amb/brand_vetripaws/inspo-pl-cat-dad.mp4', 'PrettyLitter (inspiration)', 'A dog dad holds his dog and talks straight to the other dog dads about the breath they''ve been putting up with. Keep it dry and funny, then show the strip.', '628f028815b55001', 1, 1, 23);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('0dd2644cb7c90749', 'brand_vetripaws', 'ae4bbbea42011e24', 0, 0, 24, 'live', 'Shedding season non-negotiables', 'A fast list everyone with a shedding dog recognises, and the strip lands last as the one that works from the inside.', 'Owners of heavy shedders (goldens, huskies, labs, shepherds)', 'Skin & Coat', 'Non-negotiables list, quick cuts', '["Lint roller, vacuum, brush, and this. The non-negotiables.", "Shedding season with a golden. Here''s what I can''t live without.", "Things I own because my dog sheds, ranked."]', '[{"label": "Open · 0 to 3s", "text": "Hold up a fur covered lint roller. Say: shedding season non-negotiables."}, {"label": "Middle", "text": "One quick shot each: vacuum, brush on the dog, then the tin and a strip on the tongue."}, {"label": "Close", "text": "Tin and dog together. Say: the first three clean up the fur, this one supports the coat from the inside."}]', 'You holding up a lint roller covered in dog hair: shedding season non-negotiables', 'Last cut: tin opening and the strip going on the tongue, caption: the one that works from the inside', '[{"brand": "Touchland", "what": "Quick cuts naming your shedding season must haves, one item per shot: lint roller, vacuum, brush, and the VetriPaws tin last. Say each one out loud with the dog in the shot.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('0ce9a46e4e2e4fb8', 'brand_vetripaws', '0dd2644cb7c90749', 'upload', 'amb/brand_vetripaws/inspo-tl-non-negotiables.mp4', 'Touchland (inspiration)', 'Quick cuts naming your shedding season must haves, one item per shot: lint roller, vacuum, brush, and the VetriPaws tin last. Say each one out loud with the dog in the shot.', 'ae4bbbea42011e24', 1, 1, 24);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, openers_json, shots_json, visual_hook, rehook, inspo_json) VALUES ('028d7177b37bf6ee', 'brand_vetripaws', 'b763a3101f4df13f', 0, 0, 25, 'live', 'I let my dog pick', 'Owners doubt a dog will take a supplement. Watching the dog choose it from a lineup answers that better than any claim.', 'Owners of picky dogs, or homes with more than one dog', 'Any strip', 'Lineup, let them pick', '["I put four things in front of my dog and let him pick.", "Cheese, biscuit, carrot, or a vitamin strip. Watch.", "Which one does she go for first? I genuinely didn''t know."]', '[{"label": "Open · 0 to 3s", "text": "Wide shot from floor level: the lineup, dog coming in. Caption: which one does he pick?"}, {"label": "Middle", "text": "The sniff test along the row, then the pick. Name each item as they pass it."}, {"label": "Close", "text": "Strip on the tongue, gone in about 30 seconds. Say: so that''s the vitamins sorted."}]', 'Row of options on the floor (cheese, a biscuit, a carrot, a strip), dog walking in from the side', 'Dog skips the cheese and goes for the strip, slow motion is fine', '[{"brand": "Viva Raw", "what": "Line up a few things your dog loves on the floor with a VetriPaws strip in the row, then let them choose. Film from their level. If you have more than one dog, let each one pick.", "url": null}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, file_key, who, note, section_id, shown, sort, board_sort) VALUES ('a559a87b1b1e04d4', 'brand_vetripaws', '028d7177b37bf6ee', 'upload', 'amb/brand_vetripaws/inspo-viva-let-them-pick.mp4', 'Viva Raw (inspiration)', 'Line up a few things your dog loves on the floor with a VetriPaws strip in the row, then let them choose. Film from their level. If you have more than one dog, let each one pick.', 'b763a3101f4df13f', 1, 1, 25);
